import { useId } from "react";
import type { ReactElement } from "react";
import "./ChipFilter.css";

export interface ChipOption<T extends string = string> {
  value: T;
  label: string;
}

export interface ChipFilterProps<T extends string = string> {
  label: string;
  options: readonly ChipOption<T>[];
  selected: readonly T[];
  onToggle: (value: T) => void;
}

export function ChipFilter<T extends string = string>({
  label,
  options,
  selected,
  onToggle,
}: ChipFilterProps<T>): ReactElement {
  const labelId = useId();

  return (
    <div role="group" aria-labelledby={labelId} className="chip-filter">
      <span id={labelId} className="chip-filter__label">
        {label}
      </span>
      <div className="chip-filter__chips">
        {options.map((option) => {
          const isOn = selected.includes(option.value);
          return (
            <button
              key={option.value}
              type="button"
              aria-pressed={isOn}
              className={isOn ? "chip-filter__chip is-on" : "chip-filter__chip"}
              onClick={() => onToggle(option.value)}
            >
              {option.label}
            </button>
          );
        })}
      </div>
    </div>
  );
}
```

```css
.chip-filter {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: clamp(0.5rem, 1vw, 0.75rem);
  font: inherit;
  color: var(--ink);
}

.chip-filter__label {
  font-size: clamp(0.8rem, 0.9vw, 0.95rem);
  color: var(--muted);
}

.chip-filter__chips {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.chip-filter__chip {
  display: inline-flex;
  align-items: center;
  gap: 0.45em;
  font: inherit;
  font-size: clamp(0.85rem, 1vw, 1rem);
  color: var(--ink);
  background: transparent;
  border: 1px solid var(--muted);
  border-radius: 999px;
  padding: 0.4em 0.9em;
  cursor: pointer;
  transition: background-color 150ms ease, border-color 150ms ease;
}

.chip-filter__chip::before {
  content: "";
  flex: none;
  width: 0.5em;
  height: 0.5em;
  box-sizing: border-box;
  border: 1px solid currentColor;
  border-radius: 50%;
}

.chip-filter__chip:hover {
  background: var(--myelin-wash);
}

.chip-filter__chip.is-on {
  background: var(--cresyl-wash);
  border-color: var(--cresyl);
}

.chip-filter__chip.is-on::before {
  background: currentColor;
}

.chip-filter__chip:focus-visible {
  outline: 3px solid var(--cresyl);
  outline-offset: 3px;
}

:root[data-motion="reduce"] .chip-filter__chip,
:root[data-motion="reduce"] .chip-filter__chip * {
  transition: none;
}

@media (prefers-reduced-motion: reduce) {
  .chip-filter__chip {
    transition: none;
  }
}
